const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
// argv[2] = hex string of target bytes -> print base58 string that decodes to it
function enc(bytes){
  let k=0; while(k<bytes.length && bytes[k]===0) k++;
  let acc=0n;
  for(let i=k;i<bytes.length;i++) acc = acc*256n + BigInt(bytes[i]);
  let s='';
  while(acc>0n){ const m=acc%58n; s=AL[Number(m)]+s; acc/=58n; }
  return '1'.repeat(k)+s;
}
const hex=process.argv[2]||'';
const bytes=[];
for(let i=0;i<hex.length;i+=2) bytes.push(parseInt(hex.substr(i,2),16));
process.stdout.write(enc(bytes));
EOF
