// model of Python bytes.__repr__ per F5
function repr(bytes){
  const has27=bytes.includes(0x27), has22=bytes.includes(0x22);
  const q = (has27 && !has22) ? 0x22 : 0x27;
  const qc = String.fromCharCode(q);
  let s = "b" + qc;
  for(const b of bytes){
    if(b===0x5c) s+="\\\\";
    else if(b===0x09) s+="\\t";
    else if(b===0x0a) s+="\\n";
    else if(b===0x0d) s+="\\r";
    else if(b===q) s+="\\"+qc;
    else if(b<0x20 || b>=0x7f) s+="\\x"+b.toString(16).padStart(2,"0");
    else s+=String.fromCharCode(b);
  }
  return s+qc;
}
const hex=process.argv[2]||'';
const bytes=[];
for(let i=0;i<hex.length;i+=2) bytes.push(parseInt(hex.substr(i,2),16));
process.stdout.write(repr(bytes));
EOF
